// CobPayload Dados da cobrança imediata acessados pelo payload JSON
type CobPayload struct {
	// Calendario Os campos aninhados sob o identificador calendário organizam informações a respeito de controle de tempo da cobrança.
	Calendario struct {
		// Apresentacao Timestamp que indica o momento em que o payload JSON que representa a cobrança foi recuperado. Ou seja, idealmente, é o momento em que o usuário realizou a captura do QR Code para verificar os dados de pagamento. Respeita o formato definido na RFC 3339.
		Apresentacao time.Time `json:"apresentacao"`

		// Criacao Timestamp que indica o momento em que foi criada a cobrança. Respeita o formato definido na RFC 3339.
		Criacao time.Time `json:"criacao"`

		// Expiracao Tempo de vida da cobrança, especificado em segundos a partir da data de criação (Calendario.criacao)
		//
		//
		// Example: 3600
		Expiracao int32 `json:"expiracao"`
	} `json:"calendario"`

	// Chave # Formato do campo chave
	//
	// * O campo chave determina a chave Pix registrada no DICT que será utilizada para a cobrança. Essa chave será lida pelo aplicativo do PSP do pagador para consulta ao DICT, que retornará a informação que identificará o recebedor da cobrança.
	// * Os tipos de chave podem ser: telefone, e-mail, cpf/cnpj ou EVP.
	// * O formato das chaves pode ser encontrado na seção "Formatação das chaves do DICT no BR Code" do [Manual de Padrões para iniciação do Pix](https://www.bcb.gov.br/estabilidadefinanceira/pix).
	Chave string `json:"chave"`

	// Devedor Os campos aninhados sob o objeto devedor são opcionais e identificam o devedor, ou seja, a pessoa ou a instituição a quem a cobrança está endereçada. Não identifica, necessariamente, quem irá efetivamente realizar o pagamento. Um CPF pode ser o devedor de uma cobrança, mas pode acontecer de outro CPF realizar, efetivamente, o pagamento do documento. Não é permitido que o campo `devedor.cpf` e campo `devedor.cnpj` estejam preenchidos ao mesmo tempo. Se o campo `devedor.cnpj` está preenchido, então o campo `devedor.cpf` não pode estar preenchido, e vice-versa. Se o campo `devedor.nome` está preenchido, então deve existir ou um `devedor.cpf` ou um campo `devedor.cnpj` preenchido.
	Devedor *CobPayload_Devedor `json:"devedor,omitempty"`

	// InfoAdicionais Cada respectiva informação adicional contida na lista (nome e valor) deve ser apresentada ao pagador.
	InfoAdicionais *[]struct {
		// Nome Nome do campo.
		Nome string `json:"nome"`

		// Valor Dados do campo.
		Valor string `json:"valor"`
	} `json:"infoAdicionais,omitempty"`

	// Revisao # O campo `revisao`
	//
	// Denota a revisão da cobrança.  Sempre começa em zero. Sempre varia em acréscimos de 1.
	//
	// O incremento em uma cobrança deve ocorrer sempre que um objeto da cobrança em questão for alterado.
	// O campo `loc` é uma exceção a esta regra.
	//
	// Se em uma determinada alteração em uma cobrança, o único campo alterado for o campo `loc`,
	// então esta operação não incrementa a revisão da cobrança.
	//
	// O campo `loc` não ocasiona uma alteração na cobrança em si.
	// Não é necessário armazenar histórico das alterações do campo `loc` para uma determinada cobrança.
	// Para os outros campos da cobrança, registra-se histórico.
	Revisao *Revisao `json:"revisao,omitempty"`

	// SolicitacaoPagador O campo solicitacaoPagador, opcional, determina um texto a ser apresentado ao pagador para que ele possa digitar uma informação correlata, em formato livre, a ser enviada ao recebedor. Esse texto será preenchido, na pacs.008, pelo PSP do pagador, no campo RemittanceInformation <RmtInf>. O tamanho do campo <RmtInf> na pacs.008 está limitado a 140 caracteres.
	SolicitacaoPagador *string `json:"solicitacaoPagador,omitempty"`

	// Status Estado do registro da cobrança. Não se confunde com o estado da cobrança em si, ou seja, não guarda relação com o fato de a cobrança encontrar-se vencida ou expirada, por exemplo.
	//
	// Os status são assim definidos:
	// - `ATIVA`: indica que o registro se refere a uma cobrança que foi gerada mas ainda não foi paga nem removida;
	// - `CONCLUIDA`: indica que o registro se refere a uma cobrança que já foi paga e, por conseguinte, não pode acolher outro pagamento;
	// - `REMOVIDO_PELO_USUARIO_RECEBEDOR`: indica que o usuário recebedor solicitou a remoção do registro da cobrança;
	// - `REMOVIDO_PELO_PSP`: indica que o PSP Recebedor solicitou a remoção do registro da cobrança.
	Status CobStatus `json:"status"`

	// Txid # Identificador da transação
	//
	// O campo `txid` determina o identificador da transação.
	// O objetivo desse campo é ser um elemento que possibilite ao PSP do recebedor apresentar ao usuário recebedor a funcionalidade de conciliação de pagamentos.
	//
	// Na pacs.008, é referenciado como `TransactionIdentification <txId>` ou `idConciliacaoRecebedor`.
	//
	// Em termos de fluxo de funcionamento, o txid é lido pelo aplicativo do PSP do pagador e,
	// depois de confirmado o pagamento, é enviado para o SPI via pacs.008.
	// Uma pacs.008 também é enviada ao PSP do recebedor, contendo, além de todas as informações usuais
	// do pagamento, o txid.
	// Ao perceber um recebimento dotado de txid, o PSP do recebedor está apto a se comunicar com o usuário recebedor,
	// informando que um pagamento específico foi liquidado.
	//
	// O txid é criado exclusivamente pelo usuário recebedor e está sob sua responsabilidade.
	// O txid, no contexto de representação de uma cobrança, é único por CPF/CNPJ do usuário recebedor. Cabe ao
	// PSP recebedor validar essa regra na API Pix.
	Txid TxId `json:"txid"`

	// Valor Todos os campos que indicam valores monetários obedecem ao pattern \d{1,10}\.\d{2}. O separador decimal é o caractere ponto. Não é aplicável utilizar separador de milhar. Exemplos de valores aderentes ao padrão: “1.00”, “123.99”, “123456789.23
	Valor CobPayloadValor `json:"valor"`
}

